// auxChiMuBlock: PROJ coeffs[108:129] "C[chi,mu]" — the RECTIFYING ->
// CONFORMAL series (utg in tmerc.cpp).
var auxChiMuBlock = [21]float64{
	-1.0 / 2.0, 2.0 / 3.0, -37.0 / 96.0, 1.0 / 360.0, 81.0 / 512.0, -96199.0 / 604800.0,
	-1.0 / 48.0, -1.0 / 15.0, 437.0 / 1440.0, -46.0 / 105.0, 1118711.0 / 3870720.0,
	-17.0 / 480.0, 37.0 / 840.0, 209.0 / 4480.0, -5569.0 / 90720.0,
	-4397.0 / 161280.0, 11.0 / 504.0, 830251.0 / 7257600.0,
	-4583.0 / 161280.0, 108847.0 / 3991680.0,
	-20648693.0 / 638668800.0,
}

// auxMuChiBlock: PROJ coeffs[66:87] "C[mu,chi]" — the CONFORMAL ->
// RECTIFYING series (gtu in tmerc.cpp).
var auxMuChiBlock = [21]float64{
	1.0 / 2.0, -2.0 / 3.0, 5.0 / 16.0, 41.0 / 180.0, -127.0 / 288.0, 7891.0 / 37800.0,
	13.0 / 48.0, -3.0 / 5.0, 557.0 / 1440.0, 281.0 / 630.0, -1983433.0 / 1935360.0,
	61.0 / 240.0, -103.0 / 140.0, 15061.0 / 26880.0, 167603.0 / 181440.0,
	49561.0 / 161280.0, -179.0 / 168.0, 6601661.0 / 7257600.0,
	34729.0 / 80640.0, -3418889.0 / 1995840.0,
	212378941.0 / 319334400.0,
}

// auxLatCoeffs is PROJ's pj_auxlat_coeffs for the odd-power branch (all four
// conversions tmerc uses involve CONFORMAL or RECTIFYING latitudes): the
// Maxima coefficient block is a polynomial in n of degree 5-l for F[l].
// polyval/clenshawDelta/rectifyingRadius are the shared helpers in mlfn.go
// (same package; PROJ's pj_polyval/pj_clenshaw/pj_rectifying_radius, identical
// arithmetic — reused instead of duplicated, see PROGRESS-B.md C#10).
func auxLatCoeffs(n float64, block *[21]float64) [6]float64 {
	var F [6]float64
	d := n
	o := 0
	for l := 0; l < tmercOrder; l++ {
		m := tmercOrder - l - 1
		F[l] = d * polyval(n, block[o:o+m+1])
		o += m + 1
		d *= n
	}
	return F
}

// auxLatConvert is PROJ's pj_auxlat_convert(zeta, F, K): zeta + series.
func auxLatConvert(zeta float64, F *[6]float64, K int) float64 {
	return zeta + clenshawDelta(math.Sin(zeta), math.Cos(zeta), F[:])
}

// auxLatConvertSC is the overload with sin/cos of zeta supplied.
func auxLatConvertSC(zeta, szeta, czeta float64, F *[6]float64, K int) float64 {
	return zeta + clenshawDelta(szeta, czeta, F[:])
}

// tmercClenS is PROJ's complex Clenshaw summation over the etmerc coefficient
// tables (gtu forward, utg inverse). Returns the real part R (the correction to
// the normalised northing) and the imaginary part I (easting correction).
func tmercClenS(a []float64, sinArgR, cosArgR, sinhArgI, coshArgI float64) (R, I float64) {
	p := len(a)
	r := 2 * cosArgR * coshArgI
	i := -2 * sinArgR * sinhArgI
	hr, hi := 0.0, 0.0
	hr1, hi1 := 0.0, 0.0
	first := true
	for p > 0 {
		p--
		hr2, hi2 := hr1, hi1
		hr1, hi1 = hr, hi
		if first {
			hr, hi = a[p], 0.0
			first = false
		} else {
			hr = -hr2 + r*hr1 - i*hi1 + a[p]
			hi = -hi2 + i*hr1 + r*hi1
		}
	}
	r = sinArgR * coshArgI
	i = cosArgR * sinhArgI
	return r*hr - i*hi, r*hi + i*hr
}

// tmercKernel holds the precomputed constants. Immutable, so a Projection built
// on it is thread-safe (COORDINATION §2.5).
type tmercKernel struct {
	a, e, es  float64
	lat0      float64 // radians
	lon0      float64 // radians
	k0        float64
	spherical bool
	// exact path (Poder/Engsager):
	cbg, cgb, utg, gtu [6]float64
	Qn, Zb             float64
	// spherical path (PROJ's tmerc_spherical_*):
	esp, ml0 float64
}

// newTmercKernel mirrors PROJ's tmerc setup. lat0/lon0 radians, a/b metres.
func newTmercKernel(a, b, lat0, lon0, k0 float64) *tmercKernel {
	e2 := (a*a - b*b) / (a * a)
	if e2 < 0 {
		e2 = 0
	}
	e := math.Sqrt(e2)
	q := &tmercKernel{a: a, e: e, es: e2, lat0: lat0, lon0: lon0, k0: k0}
	if e2 == 0 {
		// PROJ: the exact algorithm only exists in ellipsoidal form.
		q.spherical = true
		q.esp = k0
		q.ml0 = 0.5 * q.esp
		return q
	}
	n := (a - b) / (a + b)                   // third flattening
	q.cbg = auxLatCoeffs(n, &auxChiPhiBlock) // GEOGRAPHIC -> CONFORMAL  (Geo -> Gauss)
	q.cgb = auxLatCoeffs(n, &auxPhiChiBlock) // CONFORMAL -> GEOGRAPHIC  (Gauss -> Geo)
	q.utg = auxLatCoeffs(n, &auxChiMuBlock)  // RECTIFYING -> CONFORMAL  (transv -> geo)
	q.gtu = auxLatCoeffs(n, &auxMuChiBlock)  // CONFORMAL  -> RECTIFYING (geo -> transv)
	q.Qn = k0 * a * rectifyingRadius(n)
	// Gaussian latitude of the origin, then its rectifying coordinate; Zb is the
	// origin northing minus the true northing there.
	Z := auxLatConvert(lat0, &q.cbg, tmercOrder)
	q.Zb = -q.Qn * auxLatConvert(Z, &q.gtu, tmercOrder)
	return q
}

// forward: radians in, metres out. lon is absolute; the kernel reduces it
// against lon0 the way PROJ's pipeline does (adjlon(lon - lon0)).
func (q *tmercKernel) forward(lon, lat float64) (x, y float64) {
	lam := geoAdjLonPi(lon - q.lon0)
	if q.spherical {
		return q.forwardSph(lam, lat)
	}

	// ell. LAT, LNG -> Gaussian LAT, LNG
	Cn := auxLatConvert(lat, &q.cbg, tmercOrder)
	sinCn, cosCn := math.Sin(Cn), math.Cos(Cn)
	sinCe, cosCe := math.Sin(lam), math.Cos(lam)
	cosCnCosCe := cosCn * cosCe
	Cn = math.Atan2(sinCn, cosCnCosCe)

	// Gaussian LAT, LNG -> complex spherical LAT, LNG
	invDenomTanCe := 1 / math.Hypot(sinCn, cosCnCosCe)
	tanCe := sinCe * cosCn * invDenomTanCe
	Ce := math.Asinh(tanCe)

	// sin/cos of 2*Cn and sinh/cosh of 2*Ce from the same auxiliary quantities
	// (PROJ's algebra, kept to match its rounding).
	twoInvDenom := 2 * invDenomTanCe
	twoInvDenomSq := twoInvDenom * invDenomTanCe
	tmpR := cosCnCosCe * twoInvDenomSq
	sinArgR := sinCn * tmpR
	cosArgR := cosCnCosCe*tmpR - 1
	sinhArgI := tanCe * twoInvDenom
	coshArgI := twoInvDenomSq - 1

	// complex sph. N, E -> ell. norm. N, E
	r, i := tmercClenS(q.gtu[:], sinArgR, cosArgR, sinhArgI, coshArgI)
	Cn += r
	Ce += i
	if math.Abs(Ce) > tmercDomainCe {
		return math.NaN(), math.NaN()
	}
	return q.Qn * Ce, q.Qn*Cn + q.Zb
}

// inverse: metres in, radians out. ok == false means outside the domain.
func (q *tmercKernel) inverse(x, y float64) (lon, lat float64, ok bool) {
	if q.spherical {
		return q.inverseSph(x, y)
	}
	Cn := (y - q.Zb) / q.Qn
	Ce := x / q.Qn
	if math.Abs(Ce) > tmercDomainCe {
		return math.NaN(), math.NaN(), false
	}

	sinArgR, cosArgR := math.Sin(2*Cn), math.Cos(2*Cn)
	exp2Ce := math.Exp(2 * Ce)
	halfInvExp2Ce := 0.5 / exp2Ce
	sinhArgI := 0.5*exp2Ce - halfInvExp2Ce
	coshArgI := 0.5*exp2Ce + halfInvExp2Ce
	r, dCe := tmercClenS(q.utg[:], sinArgR, cosArgR, sinhArgI, coshArgI)
	Cn += r // PROJ: Cn += clenS(...) — the real part corrects the northing too
	Ce += dCe

	// complex sph. LAT -> Gaussian LAT, LNG (divide by cos_Ce first: PROJ's
	// comment; keeps the atan2 well-conditioned near Ce = ±pi/2).
	sinCn, cosCn := math.Sin(Cn), math.Cos(Cn)
	sinhCe := math.Sinh(Ce)
	Ce = math.Atan2(sinhCe, cosCn)
	modulusCe := math.Hypot(sinhCe, cosCn)
	rr := math.Hypot(sinCn, modulusCe)
	Cn = math.Atan2(sinCn, modulusCe)

	// Gaussian LAT, LNG -> ell. LAT, LNG (sin/cos of the Gaussian latitude are
	// supplied for accuracy near the poles).
	phi := auxLatConvertSC(Cn, sinCn/rr, modulusCe/rr, &q.cgb, tmercOrder)
	return Ce, phi, true
}

// forwardSph is PROJ's tmerc_spherical_fwd (lam already relative to lon0).
func (q *tmercKernel) forwardSph(lam, lat float64) (x, y float64) {
	coslam := math.Cos(lam)
	cosphi := math.Cos(lat)
	b := cosphi * math.Sin(lam)
	if math.Abs(math.Abs(b)-1) <= tmercEPS10 {
		return math.NaN(), math.NaN()
	}
	x = q.a * q.ml0 * math.Log((1+b)/(1-b))
	if cosphi == 1.0 {
		if lam < -math.Pi/2 || lam > math.Pi/2 {
			y = math.Pi
		} else {
			y = 0
		}
	} else {
		y = cosphi * coslam / math.Sqrt(1-b*b)
		b = math.Abs(y)
		if b >= 1 {
			if (b - 1) > tmercEPS10 {
				return math.NaN(), math.NaN()
			}
			y = 0
		} else {
			y = math.Acos(y)
		}
	}
	if lat < 0 {
		y = -y
	}
	return x, q.a * q.esp * (y - q.lat0)
}

// inverseSph is PROJ's tmerc_spherical_inv.
func (q *tmercKernel) inverseSph(x, y float64) (lon, lat float64, ok bool) {
	// PROJ's pipeline divides by P->a first; do the same here.
	h := math.Exp(x / q.a / q.esp)
	if h == 0 {
		return math.NaN(), math.NaN(), false
	}
	g := 0.5 * (h - 1/h)
	D := q.lat0 + y/q.a/q.esp
	h = math.Cos(D)
	phi := math.Asin(math.Sqrt((1 - h*h) / (1 + g*g)))
	phi = math.Copysign(phi, D)
	lam := 0.0
	if g != 0 || h != 0 {
		lam = math.Atan2(g, h)
	}
	return lam, phi, true
}

// —— frozen contract entry points (COORDINATION §2.3) ——

func tmercForward(a, b, lat0, lon0, k0 float64, lon, lat float64) (x, y float64) {
	return newTmercKernel(a, b, lat0, lon0, k0).forward(lon, lat)
}

func tmercInverse(a, b, lat0, lon0, k0 float64, x, y float64) (lon, lat float64, ok bool) {
	return newTmercKernel(a, b, lat0, lon0, k0).inverse(x, y)
}

// —— adapter ——

type tmercProj struct {
	crs    *CRS
	kernel *tmercKernel
	x0, y0 float64 // false easting / northing, metres
}

func newTmerc(c *CRS) (Projection, error) {
	a, b := c.Ellipsoid.A, c.Ellipsoid.B
	if a <= 0 || b <= 0 || b > a {
		return nil, fmt.Errorf("proj(tmerc): 椭球半轴非法 a=%v b=%v", a, b)
	}
	lat0, _ := paramFloat(c, "lat_0", 0)
	lon0, _ := paramFloat(c, "lon_0", 0)
	k0, _ := paramFloat(c, "k_0", 1)
	x0, _ := paramFloat(c, "x_0", 0)
	y0, _ := paramFloat(c, "y_0", 0)
	if math.Abs(lat0) > 90 {
		return nil, fmt.Errorf("proj(tmerc): lat_0 非法 |lat_0| > 90 (%v)", lat0)
	}
	return &tmercProj{
		crs:    c,
		kernel: newTmercKernel(a, b, geoDegToRad(lat0), geoDegToRad(lon0), k0),
		x0:     x0,
		y0:     y0,
	}, nil
}

func (s *tmercProj) CRS() *CRS { return s.crs }

func (s *tmercProj) Forward(lon, lat float64) (float64, float64, error) {
	if math.IsNaN(lon) || math.IsNaN(lat) || math.Abs(lat) > 90 || math.Abs(lon) > 360 {
		return math.NaN(), math.NaN(), fmt.Errorf("proj(tmerc): 输入出界 lon=%v lat=%v", lon, lat)
	}
	x, y := s.kernel.forward(geoDegToRad(lon), geoDegToRad(lat))
	if math.IsNaN(x) || math.IsNaN(y) {
		return math.NaN(), math.NaN(), ErrDomain
	}
	return s.x0 + x, s.y0 + y, nil
}

func (s *tmercProj) Inverse(x, y float64) (float64, float64, error) {
	lon, lat, ok := s.kernel.inverse(x-s.x0, y-s.y0)
	if !ok {
		return math.NaN(), math.NaN(), ErrDomain
	}
	// PROJ's pipeline: adjlon(lam + lam0) in radians, then to degrees.
	return geoNormLon(geoRadToDeg(geoAdjLonPi(lon + s.kernel.lon0))), geoRadToDeg(lat), nil
}

func init() { register("tmerc", newTmerc) }
